/**
 * WR-011 [critical · functional] Coupon discount is applied twice when placing an order
 * Expected: Order total equals the checkout total ($44.99 for one $49.99 item with 10% off)
 * Actual (bug): Order total charged is $40.49: the coupon is applied once in summarize() and again in the order insert
 * Source: app/api/orders/route.ts:38 — summary.total already includes the coupon (cart.ts:20); applying it again double-discounts
 */
test("WR-011: Coupon discount is applied twice when placing an order", async ({ page, context }) => {
  const consoleErrors: string[] = [];
  const serverErrors: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
  page.on("pageerror", (e) => consoleErrors.push(e.message));
  page.on("response", (r) => { if (r.status() >= 500) serverErrors.push(`${r.status()} ${r.url()}`); });
  let res: Awaited<ReturnType<typeof page.request.fetch>> | undefined;

  res = await page.request.fetch("/api/cart", { method: "POST", data: "{\"productId\": \"3\", \"quantity\": 1}" });
  res = await page.request.fetch("/api/cart/coupon", { method: "POST", data: "{\"code\":\"SAVE10\"}" });
  await page.goto("/checkout");
  await page.waitForLoadState("networkidle", { timeout: 5_000 }).catch(() => {});
  await page.getByLabel("Delivery address").first().fill("1 Wreck St");
  await page.getByRole("button", { name: "Place order" }).first().click();
  await page.waitForLoadState("networkidle", { timeout: 5_000 }).catch(() => {});
  await page.waitForTimeout(2500);

  await expect(page.getByText("Total charged").first()).toContainText("$44.99");
});
